"""python answer.py "request text" [--state state] : prints the skill name GENERATED by the compressed BitNet-2B (real generation). Label names (not feedback examples) come from state/labels.json."""
import sys, json, os, numpy as np, torch
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from l7lib import *
st = sys.argv[sys.argv.index("--state") + 1] if "--state" in sys.argv else "state"; labels = json.load(open(st + "/labels.json")) if os.path.exists(st + "/labels.json") else LABELS
S = Sys()
if os.path.exists(st + "/head_rows.npz"):
    z = np.load(st + "/head_rows.npz"); W = S.model.get_output_embeddings().weight.data
    for t, r in zip(z["tok"], z["rows"]): W[int(t)] = torch.tensor(r.astype(np.float32)).to(W.dtype).to(W.device)
print(S.answer([sys.argv[1]], labels)[0])
